auth.probe_js:
// Bluesky does NOT keep its session in a cookie. The web client writes its whole persisted store
// into localStorage under the key BSKY_STORAGE (social-app, src/state/persisted/index.web.ts),
// shaped {session:{accounts:[{service,did,handle,accessJwt?,refreshJwt?,...}],currentAccount:{did,...}}}.
// There is also no same-origin "who am I" to ask: bsky.app is a client, and every call it makes is
// XRPC to the PDS/AppView with a Bearer token — so a credentialed fetch from this origin proves
// nothing. localStorage IS the site's own state object here, so that is what this reads.
let raw = null;
try { raw = window.localStorage.getItem('BSKY_STORAGE'); }
catch (e) { return {signed_in:false, why:'localStorage unreadable on this origin: ' + e.message}; }
if (!raw) return {signed_in:false, why:'no BSKY_STORAGE key in localStorage (never signed in on this profile, or wrong origin)'};
let s = null;
try { s = JSON.parse(raw); }
catch (e) { return {signed_in:false, why:'BSKY_STORAGE is not JSON: ' + e.message}; }
const sess = (s && s.session) || {};
const accounts = Array.isArray(sess.accounts) ? sess.accounts : [];
const cur = sess.currentAccount || null;
if (!cur || !cur.did) return {signed_in:false, why:'BSKY_STORAGE holds ' + accounts.length + ' remembered account(s) but no currentAccount'};
let acct = cur;
for (const a of accounts) { if (a && a.did === cur.did) { acct = a; break; } }
// TRAP: signing out LEAVES the account in accounts[] with handle and did intact and only the
// tokens stripped (that is the account picker on the login screen). "A handle is in localStorage"
// is therefore NOT a session — the token fields are the gate.
if (!acct.accessJwt && !acct.refreshJwt) return {signed_in:false, why:'account is remembered but has no accessJwt/refreshJwt — signed out'};
let dom = '';
try {
  dom = document.querySelector('[data-testid="composeFAB"], [data-testid="viewHeaderDrawerBtn"], a[href^="/profile/"][aria-label]')
    ? '; signed-in UI present' : '';
} catch (e) { dom = ''; }
const as = acct.handle || cur.handle || cur.did;
// Never return a token. `as` is a handle or a did, both public.
return {signed_in:true, as: as, why:'BSKY_STORAGE currentAccount has session tokens' + dom};
